(function(){document.querySelectorAll('.hero-slider').forEach(function(slider){var track=slider.querySelector('[data-slider-track]'),slides=track?Array.from(track.children):[],prev=slider.querySelector('[data-slider-prev]'),next=slider.querySelector('[data-slider-next]'),pause=slider.querySelector('[data-slider-pause]'),count=slider.querySelector('[data-slider-count]');if(!track||slides.length<2){if(slider.querySelector('.slider-controls'))slider.querySelector('.slider-controls').hidden=true;return;}var index=0,paused=window.matchMedia('(prefers-reduced-motion: reduce)').matches,timer=null;function draw(){track.style.transform='translateX(-'+(index*100)+'%)';if(count)count.textContent=(index+1)+' / '+slides.length;}function step(delta){index=(index+delta+slides.length)%slides.length;draw();}function stop(){if(timer)window.clearInterval(timer);timer=null;}function start(){stop();if(!paused)timer=window.setInterval(function(){step(1)},6000);}if(prev)prev.addEventListener('click',function(){step(-1);start()});if(next)next.addEventListener('click',function(){step(1);start()});if(pause)pause.addEventListener('click',function(){paused=!paused;pause.setAttribute('aria-pressed',paused?'true':'false');pause.textContent=paused?'Oynat':'Durdur';if(paused)stop();else start();});slider.addEventListener('mouseenter',stop);slider.addEventListener('mouseleave',start);slider.addEventListener('focusin',stop);slider.addEventListener('focusout',start);if(pause){pause.setAttribute('aria-pressed',paused?'true':'false');pause.textContent=paused?'Oynat':'Durdur';}draw();start();});})();
</script></body></html>
